import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class SgfParsing {

    private String input;
    private int pos;

    public SgfNode parse(String input) throws SgfParsingException {
        this.input = input;
        this.pos = 0;
        SgfNode root = parseTree();
        if (pos != input.length()) {
            throw new SgfParsingException("Unexpected trailing characters");
        }
        return root;
    }

    // tree ::= "(" node* ")"
    private SgfNode parseTree() throws SgfParsingException {
        expect('(');
        SgfNode root = new SgfNode();
        boolean hasNodes = false;
        while (pos < input.length() && input.charAt(pos) != ')') {
            if (input.charAt(pos) == ';') {
                root.appendChild(parseNode());
                hasNodes = true;
            } else if (input.charAt(pos) == '(') {
                root.appendChild(parseTree());
                hasNodes = true;
            } else {
                throw new SgfParsingException("Expected node or tree");
            }
        }
        if (!hasNodes) {
            throw new SgfParsingException("Tree with no nodes");
        }
        expect(')');
        return root;
    }

    // node ::= ";" property*
    private SgfNode parseNode() throws SgfParsingException {
        expect(';');
        SgfNode node = new SgfNode();
        while (pos < input.length() && input.charAt(pos) != ';' && input.charAt(pos) != '(' && input.charAt(pos) != ')') {
            parseProperty(node);
        }
        return node;
    }

    // property ::= key value+
    private void parseProperty(SgfNode node) throws SgfParsingException {
        int keyStart = pos;
        while (pos < input.length() && isUppercase(input.charAt(pos))) {
            pos++;
        }
        int keyEnd = pos;
        if (keyEnd == keyStart) {
            throw new SgfParsingException("Expected property key");
        }
